package main

import (
	"encoding/json"
	"io"
	"net/http"
	"sync"
	"time"
)

var (
	failureCount int
	circuitState = "CLOSED"
	lastOpenTime time.Time
	mu           sync.Mutex
	threshold    = 3
	cooldown     = 5 * time.Second
)

func getState() string {
	mu.Lock()
	defer mu.Unlock()
	if circuitState == "OPEN" && !lastOpenTime.IsZero() && time.Since(lastOpenTime) > cooldown {
		return "HALF_OPEN"
	}
	return circuitState
}

func main() {
	go func() {
		http.HandleFunc("/upstream", func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
		})
		http.ListenAndServe(":3001", nil)
	}()

	http.HandleFunc("/circuit/status", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"state": getState(), "failureCount": failureCount})
	})

	http.HandleFunc("/proxy", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		state := getState()
		mu.Lock()
		circuitState = state
		mu.Unlock()

		if state == "OPEN" {
			w.WriteHeader(http.StatusServiceUnavailable)
			json.NewEncoder(w).Encode(map[string]string{"error": "Circuit open"})
			return
		}

		resp, err := http.Get("http://localhost:3001/upstream")
		if err != nil {
			mu.Lock()
			failureCount++
			if failureCount >= threshold {
				circuitState = "OPEN"
				lastOpenTime = time.Now()
			}
			mu.Unlock()
			w.WriteHeader(http.StatusServiceUnavailable)
			json.NewEncoder(w).Encode(map[string]interface{}{"error": "Upstream unavailable", "failureCount": failureCount})
			return
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		var data interface{}
		json.Unmarshal(body, &data)

		mu.Lock()
		failureCount = 0
		circuitState = "CLOSED"
		lastOpenTime = time.Time{}
		mu.Unlock()
		json.NewEncoder(w).Encode(data)
	})

	http.ListenAndServe(":3000", nil)
}
